// ═══ Prospecção de locadoras e revendas de carros/motos — Goiás ═══
// Ver docs/prospeccao-veiculos.md.
//
// Rode UMA fase por vez e confira o consumo no Google Cloud Console antes da
// próxima: o limite é o tier gratuito da Places API (New).
// Sem envio de WhatsApp aqui: quem dispara é o Automação IA, depois da revisão.

const FASE = 1;          // troque para avançar
const DRY_RUN = false;   // true = roda tudo, mas não grava Excel/registro de vistos

const FASES = {
  1: [ // Grande Goiânia
    { city: 'Goiânia', state: 'GO', radiusKm: 3 },
    { city: 'Aparecida de Goiânia', state: 'GO', radiusKm: 3 },
    { city: 'Senador Canedo', state: 'GO', radiusKm: 3 },
    { city: 'Trindade', state: 'GO', radiusKm: 3 },
    { city: 'Goianira', state: 'GO', radiusKm: 3 },
  ],
  2: [ // Polos do interior
    { city: 'Anápolis', state: 'GO', radiusKm: 3 },
    { city: 'Rio Verde', state: 'GO', radiusKm: 3 },
    { city: 'Jataí', state: 'GO', radiusKm: 3 },
    { city: 'Itumbiara', state: 'GO', radiusKm: 3 },
    { city: 'Catalão', state: 'GO', radiusKm: 3 },
  ],
  3: [ // Turismo — bom para locadora
    { city: 'Caldas Novas', state: 'GO', radiusKm: 3 },
    { city: 'Rio Quente', state: 'GO', radiusKm: 3 },
    { city: 'Pirenópolis', state: 'GO', radiusKm: 3 },
    { city: 'Alto Paraíso de Goiás', state: 'GO', radiusKm: 3 },
  ],
  4: [ // Entorno do DF
    { city: 'Luziânia', state: 'GO', radiusKm: 3 },
    { city: 'Valparaíso de Goiás', state: 'GO', radiusKm: 3 },
    { city: 'Águas Lindas de Goiás', state: 'GO', radiusKm: 3 },
    { city: 'Formosa', state: 'GO', radiusKm: 3 },
    { city: 'Novo Gama', state: 'GO', radiusKm: 3 },
  ],
  5: [ // Demais
    { city: 'Goianésia', state: 'GO', radiusKm: 3 },
    { city: 'Inhumas', state: 'GO', radiusKm: 3 },
    { city: 'Mineiros', state: 'GO', radiusKm: 3 },
    { city: 'Porangatu', state: 'GO', radiusKm: 3 },
    { city: 'Quirinópolis', state: 'GO', radiusKm: 3 },
  ],
};

const cities = FASES[FASE];
if (!cities) throw new Error(`Fase ${FASE} não existe`);

// Um item por segmento — o HTTP abaixo processa um de cada vez (batching = 1).
return ['locadoras-veiculos', 'revendas-veiculos'].map(segmentId => ({
  json: {
    segmentId,
    fase: FASE,
    cities: cities.map(({ city, state }) => ({ city, state })),
    radiusKm: cities[0].radiusKm,
    minReviews: 3,
    newOnly: true,
    dryRun: DRY_RUN,
  },
}));

// Resumo por segmento. Os leads ficam no Excel em ./exports — é ele que vai para
// o Automação IA (colunas WHATSAPP NÚMERO e CHAVE EXTERNA no fim da aba principal).
const configs = $('Configuração').all();

return $input.all().map((item, i) => {
  const r = item.json;
  const cfg = configs[i]?.json || {};
  const leads = r.leads || [];
  const conta = c => leads.filter(l => l.qualification?.classificacao === c).length;
  const celular = leads.filter(l => l.whatsapp).length;

  return {
    json: {
      segmento: cfg.segmentId,
      fase: cfg.fase,
      dryRun: r.dryRun,
      total: leads.length,
      quentes: conta('QUENTE'),
      mornos: conta('MORNO'),
      frios: conta('FRIO'),
      comWhatsapp: celular,
      qualificadosPorIA: leads.filter(l => l.qualification?.ai_analyzed).length,
      funil: r.funil,
      excel: r.excelPath,
    },
  };
});
